#!/usr/bin/env python3
"""
Convert .org files to separate HTML slides.
Each section (with a heading) becomes a separate HTML slide file.
Only includes sections with proper heading tags (* or **).
"""

import re
import os
from pathlib import Path
from urllib.parse import quote, urlparse
from html import escape


def parse_org_file(filepath):
    """
    Parse an .org file and extract sections with their content.

    Returns a list of tuples: (section_number, section_level, heading, content_blocks)
    """
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    sections = []
    current_section = None
    current_headings = []
    current_content = []
    current_level = 0

    for line in lines:
        line = line.rstrip('\n')

        # Check if this is a heading line (starts with * or **)
        if line.startswith(('***', '** ', '* ')):
            # Save previous section
            if current_section is not None and current_content:
                headings_text = ' '.join(current_headings)
                if headings_text:  # Only save if there's a heading
                    sections.append((len(sections)+1, current_level, headings_text, current_content))

            # Start new section
            stars = len(line.strip().replace(' ', '').replace('\t', ''))
            current_level = stars
            current_headings = [line.strip().lstrip('* \t')]
            current_content = [line]
            current_section = {'level': current_level, 'content': current_content}
        elif line.startswith('***') or line.startswith('**') or line.startswith('*'):
            # Sub-heading, add to current section
            current_headings.append(line.strip().lstrip('* \t'))
            current_content.append(line)
        elif line.startswith('#+begin_src') or line.startswith('#+') or not line.strip():
            # Skip org properties and source blocks for now
            current_content.append(line)
        elif line:
            # Regular content line
            current_content.append(line)

    # Save last section
    if current_section is not None and current_content:
        headings_text = ' '.join(current_headings)
        if headings_text:
            sections.append((len(sections)+1, current_level, headings_text, current_content))

    return sections


def is_valid_heading(headings_text):
    """Check if a heading is a valid org section heading."""
    # Remove cloaked text markers
    clean = re.sub(r'\(file:.*?\)', '', headings_text)
    clean = re.sub(r'\[image:.*?\]', 'image', clean)
    clean = re.sub(r'\[link:.*?\]', 'link', clean)
    clean = re.sub(r'\[.+?\]\(.+?\)', '', clean)
    return clean.strip()


def clean_content_for_html(content, output_path):
    """
    Clean content for HTML output.
    """
    lines = []

    for i, line in enumerate(content):
        # Skip source code blocks
        if '#+begin_src' in line:
            continue

        # Skip properties
        if line.startswith('#+') or line.startswith(':'):
            continue

        # Skip cloaked text
        if line.startswith('+#'):
            continue

        # Skip empty lines
        if not line.strip():
            continue

        # Handle image links
        if '[[' in line and ':image:' in line:
            # Extract image path
            img_match = re.search(r'(\[.+?\]:image:\s*\((.+)\)[^]]*)', line)
            if img_match:
                img_path = img_match.group(2).strip().strip('"\'')
                # Handle base64 images
                if 'base64' in line.lower() and '=;' in line.lower():
                    base64_path = os.path.join(output_path, image_filename_from_base64(img_match.group()))
                    lines.append(f'<img src="{base64_path}" alt="image data">')
                else:
                    lines.append(f'<img src="{quote(img_path)}" alt="image">')
                continue

        # Handle file links
        if '[[' in line and ':file:' in line:
            lines.append(f'<a href="{quote(line)}">{escape(line)}</a>')
            continue

        # Handle link images
        if '[[' in line and 'image:' in line:
            img_match = re.search(r'\[(.*?)\]\s+image:\s*\(([^)]*)\)\[', line)
            if img_match:
                img_path = img_match.group(2).strip().strip('"\'')
                img_name = re.sub(r'^image:.*_', '', img_path).split('.svg')[0] if '.svg' in img_path 
                else img_path.split('/')[-1].split('.')[0]
                lines.append(f'<img src="{quote(img_path)}" alt="image">')
                continue

        # Handle text with links
        if '[[' in line:
            # Remove links, keep text
            clean_line = re.sub(r'\[.*?\]\(.+?\)', '', line)
            lines.append(clean_line)
            continue

        # Handle TODO tags
        if ':@' in line:
            line = re.sub(r':@[A-Z]+:', '', line)

        # Handle cloaked sections
        if '(file:' in line:
            lines.append(f'<span class="cloaked">{escape(line)}</span>')
            lines.append(f'<a href="{line}">view file</a>')
            continue

        # Handle tags
        if ':@' in line:
            line = re.sub(r':@[A-Z]+:', '', line)

        # Handle cloaked images
        if '(file:' in line or image_filename_from_base64:
            lines.append(f'<img src="{quote(image_filename_from_base64)}" alt="image">')
            continue

        # Handle math/latex
        if '\\begin' in line or '\\"' in line:
            lines.append(f'<p><span class="math">{escape(line)}</span></p>')
            continue

        lines.append(line)

    return lines


def process_heading(headings):
    """Process headings to create a clean title."""
    heading = ' '.join(headings)

    # Remove cloaked text and special markers
    heading = re.sub(r'\(file:.*?\)', '', heading)
    heading = re.sub(r'\[image:.*?\]', 'image', heading)
    heading = re.sub(r'\[link:.*?\]', '', heading)
    heading = re.sub(r'\[.*?\]\(', '', heading)
    heading = re.sub(r'\{.*?\}', '', heading)
    heading = re.sub(r'\[.+?\]', '', heading)
    heading = heading.strip()

    return heading


