    clean = re.sub(r'\[.*?\]\(', '', clean)
    clean = re.sub(r'\[.+?\]', '', clean)
    clean = clean.strip()
    return len(clean) > 2


def extract_org_content(content):
    """Extract meaningful content from org format."""
    lines = []

    for line in content:
        # Skip source blocks
        if '#+begin_src' in line:
            # Find corresponding end and extract results
            start_idx = line.find('#+begin_src')
            if start_idx != -1:
                end_idx = content.find('#+end_src', start_idx + 1)
                if end_idx == -1:
                    continue
                code_block = content[start_idx + 15:end_idx + 9]
                lines.append(f'<pre><code>{escape(code_block)}</code></pre>')
            continue

        # Skip properties
        if line.startswith('#+') or line.starts with(':'):
            continue

        # Skip cloaked text
        if line.startswith('+#'):
            continue

        # Skip empty lines
        if not line.strip():
