        clean_line = re.sub(r'\(file:.*?\)', 'FILE', line)
        clean_line = re.sub(r'\[image:.*?\]', 'IMAGE', clean_line)
        clean_line = re.sub(r'\[link:.*?\]', 'LINK', clean_line)
