def process_heading(heading):
    """Process heading to remove cloaked content."""
    heading = ' '.join(heading).strip()
    heading = re.sub(r'\(file:.*?\)', '', heading)
    heading = re.sub(r'\[image:.*?\]', '', heading)
    heading = re.sub(r'\[link:.*?\]', '', heading)
    heading = re.sub(r'\[.+?\]\(', '', heading)
    heading = re.sub(r'\[.+?\]', '', heading)
    heading = re.sub(r'\{.*?\}', '', heading)
    heading = re.sub(r'#+name:\s*', '', heading)
    heading = re.sub(r':@TODO:', '', heading)
    heading = re.sub(r':@$TODO:', '', heading)
    heading = re.sub(r':@[^:]+:', '', heading)
    heading = re.sub(r':#+', '', heading)
    heading = heading.strip()
    return heading if heading else 'Section'

def heading_to_slug(heading):
    """Convert heading to URL-safe slug."""
    heading = process_heading(heading)
    heading = heading[:50] if len(heading) > 50 else heading
    slug = re.sub(r'[^_\w\s_-]', '', heading).lower().strip()
    slug = re.sub(r'\s+', '-', slug)
    slug = re.sub(r'--+', '-', slug)
    slug = re.sub(r'[-_]+', '-', slug)
    slug = re.sub(r'[\(\)\[\]\:\;\{\}]+', '', slug)
    slug = slug[:50] if len(slug) > 50 else slug
    return slug if slug else 'section'

def clean_content_multiline(content):
    """Clean content lines for HTML, preserving paragraphs."""
    lines = []
    current_para = []
    for line in content:
        if not line.startswith('*'):
            continue
        if line.strip() == '' or not line.strip():
            continue
        clean = line
        clean = re.sub(r'\(file:.*?\)', 'FILE', clean)
        clean = re.sub(r'\[image:.*?\]', '', clean)
        clean = re.sub(r'\[link:.*?\]', '', clean)
        clean = re.sub(r'\[.+?\]\(', '', clean)
        clean = re.sub(r'#+', '', clean)
        clean = re.sub(r'^\{', '', clean)
        clean = re.sub(r'$', '', clean)
        clean = re.sub(r':@', '', clean)
        if clean.strip():
            if clean.startswith('*'):
                clean = clean[1:]
            current_para.append(clean)
        lines.append(current_para)
        current_para = []
    return lines

def create_html_slide(heading, content_lines):
    """Create HTML slide for a section."""
    heading = process_heading(heading)
    content_lines = clean_content_multiline(content_lines)
    slug = heading_to_slug(heading)
    lines_html = ''.join(''.join(para) + '\n' for para in content_lines)
    return heading, lines_html

def parse_org_file(org_file):
    """Parse .org file and extract h1 sections."""
    with open(org_file) as f:
        content = f.read()

    sections = []
    current_heading = []
    current_content = []
    current_level = 0

    for line in content.split('\n'):
        line = line.rstrip()

        if line.startswith('***') or (line.startswith('** ') and line[2].strip()):
            if current_heading and current_content:
                heading_text = ' '.join(current_heading).strip()
                if heading_text:
                    sections.append((len(sections)+1, current_level, heading_text, current_content))
                else:
                    sections.append((len(sections)+1, current_level, 'Section', current_content))
            current_heading = [line.strip().lstrip(' *')]
            current_content = [line.lstrip('** ')]
            current_level = 1
        elif line.startswith('*'):
            current_heading.append(line.strip().lstrip('*'))
            current_content.append(line.lstrip('*'))
        else:
            if current_heading:
                current_heading.append(line)
                current_content.append(line)

    if current_heading and current_content:
        heading_text = ' '.join(current_heading).strip()
        if heading_text:
            sections.append((len(sections)+1, current_level, heading_text, current_content))
        else:
            sections.append((len(sections)+1, current_level, 'Section', current_content))

    return sections

