def main():
    import argparse

    parser = argparse.ArgumentParser(
        description='Convert .org files to HTML slides with navigation',
        epilog='Example: python3 org_to_slides.py /path/to/org_files -o slides'
    )
    parser.add_argument('directory', help='Directory containing .org files')
    parser.add_argument('-o', '--output', help='Output directory (default: {dir}/html)')
    args = parser.parse_args()

    input_path = Path(args.directory).resolve()
    org_files = sorted([f for f in input_path.glob('*.org') if not f.name.startswith('.')], key=lambda f: f.name)

    if not org_files:
        print(f'No .org files found in {input_path}')
        return

    if args.output:
        output_dir = Path(args.output).resolve()
    else:
        output_dir = input_path / 'html'

    output_dir.mkdir(parents=True, exist_ok=True)

    print(f'Converting .org files to HTML slides with navigation...')
    print(f'Input:  {input_path}')
    print(f'Output: {output_dir}')
    print(f'Found  {len(org_files)} .org files')
    print('=' * 60)

    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M')
    total_slides = 0

    for org_file in org_files:
        print(f'\n📁 {org_file.name}')
        print('=' * 60)

        sections = parse_org_file(org_file)
        sections_html = ''

        if not sections:
            print(f'  ⚠️ No h1 sections found')
            continue

        for index in range(len(sections)):
            section_num, level, heading, content_lines = sections[index]
            heading, lines_html = create_html_slide(heading, content_lines)

            if not lines_html.strip():
                continue

            section_html = create_org_html(heading + f' - Section {index + 1}', lines_html, section_num)
            sections_html += section_html
            total_slides += 1

        print(f'  ✨ Converted {total_slides} section(s)')

        file_slug = org_file.name.replace('.org', '')
        html_path = str(output_dir / (file_slug + '.html'))

        if sections_html:
            with open(html_path, 'w', encoding='utf-8') as f:
                f.write(sections_html)

        file_blocks.append(f'''<div class="file-card" onclick="location.href='{file_slug}.html'">
    <h3 style="color: #4fc3f7; margin: 0 0 8px;">📁 {file_slug}</h3>
    <span style="color: #4fc3f7; font-size: 1.5rem; margin-bottom: 5px;">{total_slides} slide(s)</span>
    <p style="color: #999; font-size: 0.85rem; margin: 5px 0 0;">Click to view all sections</p>
</div>''')

    print(f'\n' + '=' * 60)
    print(f'✓ Conversion complete!')
    print(f'Total slides: {total_slides}')
    print(f'Output: {output_dir}')
    print(f'\n  - index.html (list of all org files)')
    print(f'  - *.html (each org file with slides)')

    index_html = create_index_html(org_files)
    index_path = output_dir / 'index.html'
    with open(index_path, 'w', encoding='utf-8') as f:
        f.write(index_html)

    return total_slides

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Convert .org files to single HTML with sections and pager."""
import re
from pathlib import Path
from html import escape
from datetime import datetime

def process_heading(heading):
    """Process heading to remove cloaked content."""
    heading = ' '.join(heading).strip()
    heading = re.sub(r'\(file:.*?\)', '', heading)
    heading = re.sub(r'\[image:.*?\]', '', heading)
    heading = re.sub(r'\[link:.*?\]', '', heading)
    heading = re.sub(r'\[.+?\]\(', '', heading)
    heading = re.sub(r'\[.+?\]', '', heading)
    heading = re.sub(r'\{.*?\}', '', heading)
    heading = re.sub(r'#+name:\s*', '', heading)
    heading = re.sub(r':@TODO:', '', heading)
    heading = re.sub(r':@$TODO:', '', heading)
    heading = re.sub(r':@[^:]+:', '', heading)
    heading = re.sub(r':#+', '', heading)
    heading = heading.strip()
    return heading if heading else 'Section'

def heading_to_slug(heading):
    """Convert heading to URL-safe slug."""
    heading = process_heading(heading)
    heading = heading[:50] if len(heading) > 50 else heading
    slug = re.sub(r'[^_\w\s_-]', '', heading).lower().strip()
    slug = re.sub(r'\s+', '-', slug)
    slug = re.sub(r'--+', '-', slug)
    slug = re.sub(r'[-_]+', '-', slug)
    slug = re.sub(r'[\(\)\[\]\:\;\{\}]+', '', slug)
    slug = slug[:50] if len(slug) > 50 else slug
    return slug if slug else 'section'

def clean_content_multiline(content):
    """Clean content lines for HTML, preserving paragraphs."""
    lines = []
    for line in content:
        if not line.startswith('*'):
            continue
        if line.strip() == '' or not line.strip():
            continue
        clean = line
        clean = re.sub(r'\(file:.*?\)', 'FILE', clean)
        clean = re.sub(r'\[image:.*?\]', '', clean)
        clean = re.sub(r'\[link:.*?\]', '', clean)
        clean = re.sub(r'\[.+?\]\(', '', clean)
        clean = re.sub(r'#+', '', clean)
        clean = re.sub(r'^\{', '', clean)
        clean = re.sub(r'$', '', clean)
        clean = re.sub(r':@', '', clean)
        if clean.strip():
            if clean.startswith('*'):
                clean = clean[1:]
            lines.append(clean)
    return lines

def parse_org_file(org_file):
    """Parse .org file and extract h1 sections."""
    with open(org_file) as f:
        content = f.read()

    sections = []
    current_heading = []
    current_content = []
    current_level = 0

    for line in content.split('\n'):
        line = line.rstrip()

        if line.startswith('***') or (line.startswith('** ') and line[2].strip()):
            if current_heading and current_content:
                heading_text = ' '.join(current_heading).strip()
                if heading_text:
                    sections.append((len(sections)+1, current_level, heading_text, current_content))
                else:
                    sections.append((len(sections)+1, current_level, 'Section', current_content))
            current_heading = [line.strip().lstrip(' *')]
            current_content = [line.lstrip('** ')]
            current_level = 1
        elif line.startswith('*'):
            current_heading.append(line.strip().lstrip('*'))
            current_content.append(line.lstrip('*'))
        else:
            if current_heading:
                current_heading.append(line)
                current_content.append(line)

    if current_heading and current_content:
        heading_text = ' '.join(current_heading).strip()
        if heading_text:
            sections.append((len(sections)+1, current_level, heading_text, current_content))
        else:
            sections.append((len(sections)+1, current_level, 'Section', current_content))

    return sections

