#!/usr/bin/env python3
"""Convert .org files to HTML slides with proper org-mode parsing and navigation."""
import argparse
from pathlib import Path
from datetime import datetime, timezone
from html import escape

def extract_sections(org_content):
    """Extract sections from org content."""
    lines = org_content.split('\n')
    sections = []
    current_section = {'lines': [], 'title': None}
    in_preamble = True

    for line in lines:
        # Skip preamble
        if line.strip().startswith('#+') or (line.startswith('#') and '==' not in line):
            continue

        # Skip section property lines
        if line.strip() in ['==', '=', '= ']:
            continue

        # New section header
        if line.strip().startswith('=='):
            if current_section['lines'] or current_section['title']:
                if current_section['title']:
                    sections.append({
                        'title': current_section['title'],
                        'content': ' '.join(current_section['lines']).strip()
                    })
                else:
                    sections.append({
                        'title': line.strip('= ').strip('*').split('= ')[1].strip() if '= ' in line else 'Section',
                        'content': ' '.join(current_section['lines']).strip() if current_section['lines'] else ''
                    })

            current_section = {'lines': [], 'title': None}
        elif line.strip().startswith('='):
            # Check if it's a section header
            title = line.strip('=').strip()
            if not title:
                continue
            if current_section['title']:
                sections.append({
                    'title': current_section['title'],
                    'content': ' '.join(current_section['lines']).strip()
                })
            current_section = {'lines': [], 'title': title}
        else:
            current_section['lines'].append(line.rstrip())

    # Last section
    if current_section['title'] or current_section['lines']:
        if current_section['title']:
            sections.append({
                'title': current_section['title'],
                'content': ' '.join(current_section['lines']).strip()
            })
        else:
