def parse_org_content(org_content):
    """Parse org content into sections."""
    lines = org_content.split('\n')
    sections = []
    current_section = {'lines': [], 'title': None}
    in_preamble = True
    depth = 0

    for line in lines:
        stripped = line.strip()

        # Skip preamble
        if stripped.startswith('#+') and not stripped.startswith('=') and not stripped.startswith('*'):
            continue

        # Skip empty lines during preamble
        if stripped.startswith('#') and not stripped.startswith('=') and not stripped.startswith('*'):
            if not in_preamble:
                current_section['lines'].append(line)
            continue

        # Section header detection
        if stripped.startswith('==') or stripped.startswith('='):
            # New section
            if current_section['lines'] or current_section['title']:
                if current_section['title']:
                    sections.append({
                        'title': current_section['title'],
                        'content': ' '.join(current_section['lines']).strip()
                    })

            # Parse title
            title = stripped.replace('= ', '').replace('=' * 68, '', 1).strip('*')
            current_section = {'lines': [], 'title': title}
            continue

        # List item (tree)
        if stripped.startswith('*') or '::' in line:
            if line.strip() == '' or line.strip().startswith('*') or line.strip().startswith('::'):
                current_section['lines'].append(line)
            continue

        # Code block start/end
        if '#+end_src' in stripped:
            pass
        if '#+begin_' in stripped:
            pass

        # Regular content
        current_section['lines'].append(line)

    # Last section
    if current_section['lines'] or current_section['title']:
        sections.append({
            'title': current_section['title'] or 'Conclusions',
            'content': ' '.join(current_section['lines']).strip()
        })

    return [s for s in sections if s['title'] and len(s['content']) > 100]

def format_paragraphs(content):
    """Split content into paragraphs."""
    if not content:
