    lines = org_content.split('\n')
    sections = []
    current_section = {'title': None, 'content': []}

    for line in lines:
        stripped = line.rstrip()

        # Skip comments, headers to process
        if stripped.startswith('#') or stripped.startswith('==') or stripped.startswith('='):
            continue

        # Skip blank lines
        if not stripped.strip():
            continue

        # Section header: "=title=" or "=title:="
        if stripped.startswith('===') and stripped.endswith('==='):
            continue
        if '(' not in stripped[1:] or ')' not in stripped[1:]:
            current_section['title'] = stripped
            current_section['content'] = []

    # Check last section
    if current_section['title']:
        content_text = '\n\n'.join(current_section['content'])
        if len(content_text.strip()) > 50:
            sections.append(current_section)

    return sections

def format_content(content):
    """Format content with proper paragraphs."""
    if not content.strip():
        return []

    paragraphs = []
    for para in content.split('\n\n'):
        para = para.strip()
        if para:
            lines = para.replace('\n', ' ').split('.')
            para_parts = [p + '.' for p in lines if p.strip()]
            paragraphs.append(' '.join(para_parts))

    return paragraphs if paragraphs else [content.strip()]

