        # Skip empty header lines
        if not stripped or stripped.strip().startswith('=') or stripped.strip().startswith('*'):
            if stripped.strip().startswith('*') and len(stripped) == 1:
                continue

        # Detect section header: "* title" or "=- title -" pattern
        if stripped.startswith('==') or '==' in stripped or stripped.startswith('= '):
            title = re.sub(r'^=\s*', '', stripped.strip())
            title = re.sub(r'\s+==\s*$', '', title).strip('*:')
            current_section = {'title': title, 'content': []}
            in_section = False
            continue

        # Regular content - add to current section
        if in_section or current_section['title']:
            current_section['content'].append(line.strip())
        else:
            preamble_lines.append(line.strip())

    # Process last section
    if current_section['title']:
        content_text = '\n'.join(current_section['content'])
        if len(content_text.strip()) > 50:
            sections.append(current_section)

    return sections

def format_content(content, max_lines=6):
    """Limit content to first N lines."""
    lines = content.split('\n')[:max_lines]
    return '\n'.join(lines).strip()

