    return sections

def extract_org_links(content):
    """Extract Org links [[url][display]] including commands."""
    if not content:
        return []

    links = []
    # Match [[anything][anything]] pattern (handles [[shell:...][text]], [[http:...][text]], [[file:...][text]], etc.)
    pattern = r"\[\[([^\]]+)\]\]\[([^\]]*)\]"

    for match in re.finditer(pattern, content):
        url_full = match.group(1).strip()
        display = match.group(2).strip()

