<h3>Table of Contents</h3>
<ul>
''' + ''.join(toc_items) + '''
</ul>
</div>'''
    else:
        content_lines = s['content'] if s['content'] else ['<em>No specific content listed</em>']
        html += f'''<div id="{s['id']}" class="slide active">
<h2>{title_escaped}</h2>
<pre>{''.join(content_lines)}</pre>
<div class="links">{links_content}</div>
</div>
'''

# Add nav footer
html += '''<footer class="nav-footer">
<div class="nav-controls">
<button class="btn btn-prev" data-slide="-1">Previous</button>
<button class="btn btn-next" data-slide="1">Next</button>
<button class="btn btn-top">Top</button>
</div>
</footer>
<script src="./js/script.js"></script>
</body>
</html>'''

# Write file
with open('agent_call.html', 'w') as f:
    f.write(html)

print("HTML generated!")
print(f"  - agent_call.html")
print(f"  - css/style.css")
print(f"  - js/script.js")
print(f"Sections: {len(sections)-1}")
PYEOF

echo "Slides generated successfully!"
